/**
 * Failure analysis + correction. Kept deliberately small (self-healing is not a core goal):
 *   1. an LLM triages the failure into a category;
 *   2. only fixable categories trigger regeneration — real application defects and environment
 *      problems are surfaced for human review instead of being "healed" away.
 *
 * Web specs are regenerated by resuming the authoring agent from the last working step
 * (see ../web/author.ts). API specs get corrected expectations/requests from a structured model
 * answer. Triage prompt shape follows ai-testing-agent's failure analyser (MIT): root cause,
 * likely category, recommended fix.
 */
import type { Browser } from "playwright";
import { z } from "zod";
import type { EngineContext } from "../context.js";
import { StepSchema, type Scenario, type Step, type TestSpec } from "../spec/schema.js";
import type { AppModel } from "../understanding/app-model.js";
import { authorWebSpec } from "../web/author.js";
import type { ScriptRun } from "./runner.js";

const TriageSchema = z.object({
    category: z.enum(["locator", "timing", "test_data", "assertion", "app_defect", "environment", "other"]),
    fixable: z.boolean().describe("true if the TEST is wrong and can be corrected; false if the application or environment is at fault"),
    reason: z.string().describe("One or two sentences, factual"),
    firstWrongStep: z
        .number()
        .int()
        .min(1)
        .optional()
        .describe("1-based number of the FIRST step that is wrong, if it is earlier than the step that failed (e.g. a stray navigation or duplicated actions before the failure)"),
});

export interface Repair {
    verdict: "fixed" | "app_defect" | "unfixable";
    reason: string;
    spec?: TestSpec;
}

function failureText(spec: TestSpec, run: ScriptRun): string {
    const failed = run.steps.find((s) => s.status === "failed");
    return [
        `Status: ${run.status}`,
        failed ? `Failed step: ${failed.title}` : "No individual step failed (timeout, setup or syntax problem).",
        `Error: ${(failed?.error ?? run.error ?? "unknown").slice(0, 1200)}`,
        // What the page showed at the failing check (Playwright's error context): the elements really there, with their names.
        ...(run.errorContext ? [`What the page showed when it failed (accessibility snapshot):\n${run.errorContext.slice(0, 4000)}`] : []),
    ].join("\n");
}

export async function triage(ctx: EngineContext, spec: TestSpec, run: ScriptRun) {
    return ctx.llm.object({
        system: `You analyse why an automatically generated end-to-end/API test failed when executed.
Decide whether the TEST is wrong (bad locator, race condition, wrong test data, wrong expectation) or whether the APPLICATION/ENVIRONMENT is at fault
(feature broken, server error, network/DNS problem, blocked by captcha/bot protection). Be conservative: only mark fixable=true if a test change would plausibly make it pass.`,
        prompt: `Test: ${spec.testId} ${spec.title} (${spec.kind})
Expected results: ${spec.expectedResults.join("; ") || "n/a"}
Steps:
${spec.steps.map((s, i) => `${i + 1}. ${JSON.stringify(s)}`).join("\n")}

${failureText(spec, run)}`,
        schema: TriageSchema,
        maxOutputTokens: 600,
        purpose: "repair",
    });
}

export async function repairWeb(args: {
    ctx: EngineContext;
    browser: Browser;
    baseUrl: string;
    model: AppModel;
    scenario: Scenario;
    spec: TestSpec;
    run: ScriptRun;
    credentials?: { username: string; password: string };
    /** 1-based repair attempt for this test. Later attempts re-author from scratch. */
    attempt?: number;
}): Promise<Repair> {
    const { ctx, spec, run } = args;
    const t = await triage(ctx, spec, run);
    ctx.emit({
        stage: "validation",
        kind: "failure_analyzed",
        level: "warn",
        message: `${spec.testId} failed (${t.category}): ${t.reason}`,
        data: { testId: spec.testId, category: t.category, fixable: t.fixable },
    });
    if (t.category === "app_defect" || t.category === "environment" || !t.fixable) {
        return { verdict: t.category === "app_defect" ? "app_defect" : "unfixable", reason: t.reason };
    }

    // Keep the steps before the first *wrong* one — which can be earlier than the failing step (a stray
    // navigation that still "works" only breaks a later assertion). If a resumed repair already failed,
    // re-author from scratch instead of rebuilding on the same prefix.
    const failedAt = run.failedStepIndex >= 0 ? run.failedStepIndex : 1;
    const wrongAt = t.firstWrongStep !== undefined ? t.firstWrongStep - 1 : failedAt;
    const cut = (args.attempt ?? 1) > 1 ? 1 : Math.min(failedAt, wrongAt);
    const prefix = spec.steps.slice(0, Math.max(1, cut));
    const outcome = await authorWebSpec({
        ctx,
        browser: args.browser,
        baseUrl: args.baseUrl,
        model: args.model,
        scenario: args.scenario,
        credentials: args.credentials,
        resume: { prefix, failure: failureText(spec, run) },
    });
    if (outcome.status === "complete") {
        return { verdict: "fixed", reason: t.reason, spec: { ...spec, steps: outcome.steps, testData: { ...spec.testData, ...outcome.testData } } };
    }
    if (outcome.status === "defect") return { verdict: "app_defect", reason: outcome.explanation };
    return { verdict: "unfixable", reason: outcome.explanation };
}

const ApiRepairSchema = z.object({
    verdict: z.enum(["fix", "app_defect", "unfixable"]),
    reason: z.string(),
    steps: z.array(StepSchema).optional().describe("Complete replacement step list when verdict=fix"),
});

export async function repairApi(ctx: EngineContext, spec: TestSpec, run: ScriptRun, endpointDoc: unknown): Promise<Repair> {
    const t = await triage(ctx, spec, run);
    ctx.emit({
        stage: "validation",
        kind: "failure_analyzed",
        level: "warn",
        message: `${spec.testId} failed (${t.category}): ${t.reason}`,
        data: { testId: spec.testId, category: t.category, fixable: t.fixable },
    });
    if (t.category === "environment") return { verdict: "unfixable", reason: t.reason };

    const out = await ctx.llm.object({
        system: `You correct a failing API test. The test was generated from an API description and executed against the real service.
If the service legitimately behaves differently from what the test assumed (e.g. returns 422 instead of 400, a different status class, a different body shape), correct the test's request/assertions to match the real behaviour **only when that behaviour is reasonable and not a security or correctness defect**.
If the service behaves in a way that is a real defect (5xx on bad input, unauthenticated access allowed, injection reflected), answer verdict=app_defect and keep the test unchanged.
Never loosen an assertion just to make it pass.`,
        prompt: `Spec:
${JSON.stringify({ title: spec.title, steps: spec.steps, expectedResults: spec.expectedResults }, null, 1)}

Endpoint documentation:
${JSON.stringify(endpointDoc ?? null).slice(0, 3000)}

${failureText(spec, run)}

Triage: ${t.category} — ${t.reason}`,
        schema: ApiRepairSchema,
        maxOutputTokens: 3000,
        purpose: "repair",
    });

    if (out.verdict === "fix" && out.steps?.length) {
        const rejected = weakensApiTest(spec, out.steps as Step[]);
        if (rejected) {
            ctx.emit({ stage: "validation", kind: "repair_rejected", level: "warn", message: `${spec.testId}: proposed fix rejected — ${rejected}` });
            return { verdict: "unfixable", reason: `${t.reason} (proposed fix rejected: ${rejected})` };
        }
        return { verdict: "fixed", reason: out.reason, spec: { ...spec, steps: out.steps as Step[] } };
    }
    return { verdict: out.verdict === "app_defect" ? "app_defect" : "unfixable", reason: out.reason };
}

/**
 * Structural guard on LLM API repairs ("never loosen an assertion" must not rely on the prompt alone).
 * A repair may change expected values, but must keep the same requests (method, path, auth mode), keep at
 * least as many response assertions, and may not change the expected status of security/auth tests.
 * Returns a reason when the proposal is rejected.
 */
export function weakensApiTest(original: TestSpec, proposed: Step[]): string | undefined {
    const reqs = (steps: Step[]) =>
        steps.filter((s): s is Extract<Step, { action: "request" }> => s.action === "request").map((s) => `${s.method} ${s.path} auth=${s.auth}`);
    const before = reqs(original.steps);
    const after = reqs(proposed);
    if (before.join("|") !== after.join("|")) return "requests changed (method, path or auth mode)";
    const asserts = (steps: Step[]) => steps.filter((s): s is Extract<Step, { action: "assertResponse" }> => s.action === "assertResponse");
    if (asserts(proposed).length < asserts(original.steps).length) return "response assertions removed";
    if (original.type === "security" || original.tags.includes("auth")) {
        const statuses = (steps: Step[]) =>
            asserts(steps)
                .filter((s) => s.check === "status" || s.check === "statusClass" || s.check === "statusBelow")
                .map((s) => `${s.check}=${s.expected}`)
                .join("|");
        if (statuses(original.steps) !== statuses(proposed)) return "expected status of a security test changed";
    }
    return undefined;
}
